values
  ('9d52de8c-1183-516c-806d-b67896daca9e', null, (select id from public.skills where slug = 'read-g11-context-clues'), null, 'hard',
   $q$In paragraph 4, how does the phrase "rather than in one sweeping change" help clarify the meaning of "incremental"?$q$, $q$[{"text":"It suggests that incremental means expensive, since sweeping changes would cost the city less.","is_correct":false,"misconception_token":"unrelated-meaning"},{"text":"It shows that incremental means the changes are too slow to make any real difference to residents.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It contrasts gradual progress with sudden, complete change, showing incremental means happening in small steps.","is_correct":true},{"text":"It defines incremental as a single large project carried out by the whole city at one time.","is_correct":false,"misconception_token":"ignores-contrast"}]$q$::jsonb, $q$It contrasts gradual progress with sudden, complete change, showing incremental means happening in small steps.$q$, $q$The phrase sets up a contrast: progress comes "in small steps, block by block," not "in one sweeping change," so incremental means gradual. Claiming the changes make no difference ignores the paragraph's point that they add up over time.$q$, 'draft', '5427689b-ca11-5ac5-b4d7-a69744413f67')
