  ('8ca6ab11-f332-5329-8a2b-7b5ecfcf644a', null, (select id from public.skills where slug = 'read-g11-evidence-inference'), null, 'medium',
   $q$What can most reasonably be inferred from the kinds of articles volunteers chose to correct?$q$, $q$[{"text":"Volunteers were assigned articles by library staff based on their skills.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Many volunteers were likely drawn by interest in local people and places.","is_correct":true},{"text":"Shipping schedules and grain prices were already scanned without errors.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Most volunteers were professional historians studying local business.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Many volunteers were likely drawn by interest in local people and places.$q$, $q$Volunteers mostly corrected articles "about local families and businesses" and rarely touched tables of schedules and prices, which suggests personal or community interest guided their choices. Nothing says the schedules were error free; they were simply "rarely touched."$q$, 'draft', '914ee808-4690-58a9-b0a8-2131e39903e0')
