values
  ('59c0c639-8f88-5cc0-9455-c60cbf33982c', null, (select id from public.skills where slug = 'read-g11-evidence-inference'), null, 'medium',
   $q$Which evidence best supports Wierzbicki's warning that a researcher who finds no results for a name in 1860 should not assume it was never printed?$q$, $q$[{"text":"About six hundred volunteers corrected roughly nine thousand articles during the first year of the project.","is_correct":false,"misconception_token":"supports-different-claim"},{"text":"The library built a cradle that held each book open while an overhead camera photographed its pages.","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"The software matched a human transcriber on about ninety-eight of every hundred words on pages from the 1960s and 1970s.","is_correct":false,"misconception_token":"wrong-time-period"},{"text":"On pages from before 1880, the software matched a human transcriber on only about seventy of every hundred words.","is_correct":true}]$q$::jsonb, $q$On pages from before 1880, the software matched a human transcriber on only about seventy of every hundred words.$q$, $q$An 1860 page falls in the period where roughly thirty words in a hundred are misread, so a printed name could easily be missed by a search. The ninety-eight percent figure describes much later pages, so it does not support the warning.$q$, 'draft', '914ee808-4690-58a9-b0a8-2131e39903e0')
