values
  ('a7fdc978-7600-569d-a266-65518530799e', null, (select id from public.skills where slug = 'read-g11-evidence-inference'), null, 'hard',
   $q$How does the detail about two other figureless paintings by Ensing relate to the question of why the woman was painted over?$q$, $q$[{"text":"It shows that a later owner, not Ensing, covered the sketched figure.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It proves that a buyer asked Ensing to paint landscapes without people.","is_correct":false,"misconception_token":"overstates-certainty"},{"text":"It suggests that Ensing lacked the skill to paint human figures well.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It lends some support to the idea that the choice was Ensing's own, but it does not settle it.","is_correct":true}]$q$::jsonb, $q$It lends some support to the idea that the choice was Ensing's own, but it does not settle it.$q$, $q$Staff members note the other paintings "could reflect his own preference," which is possible support, while the buyer explanation remains open and the letters are silent. The detailed sketch, with folds and a shaded face, argues against the claim that he lacked skill.$q$, 'draft', 'd6472840-821c-5e15-81d4-1854bb9fc0dc')
