  ('9b1bea26-eecc-5068-8aa4-cd979532454d', null, (select id from public.skills where slug = 'read-g11-figurative-language'), null, 'easy',
   $q$The narrator says the hallway "sounded like a hundred radios arguing at once." What does this description suggest?$q$, $q$[{"text":"The hallway was filled with many loud, clashing sounds.","is_correct":true},{"text":"Several students had brought radios to play backstage.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The orchestra was already playing together in perfect tune.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The musicians were having an angry argument with each other.","is_correct":false,"misconception_token":"misreads-target"}]$q$::jsonb, $q$The hallway was filled with many loud, clashing sounds.$q$, $q$The exaggerated comparison captures the noise of squeaking violins, a groaning tuba and a cymbal all sounding at once. No one is actually arguing; "arguing" describes sounds that clash, not people who disagree.$q$, 'draft', 'b5771e20-4539-5867-a8a1-125a9250a969')
