values
  ('781b3ff7-ba8e-5e9d-a534-3bce6e78a560', null, (select id from public.skills where slug = 'read-g11-figurative-language'), null, 'easy',
   $q$Halfway up the hill, Priya's "legs turned to wet cardboard." What does this phrase mean?$q$, $q$[{"text":"Her legs became weak and floppy from exhaustion.","is_correct":true},{"text":"Her legs felt light and fast as she sped up.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Her legs got soaked because it began to rain.","is_correct":false,"misconception_token":"literal-reading"},{"text":"Her legs became stiff and hard to bend at all.","is_correct":false,"misconception_token":"misreads-comparison"}]$q$::jsonb, $q$Her legs became weak and floppy from exhaustion.$q$, $q$Wet cardboard is soft and collapses, so the comparison shows her legs giving out, which is why "all three girls passed her back." Stiff legs would be closer to dry cardboard, so that reading misses what "wet" adds.$q$, 'draft', '58f2c27b-5111-5491-9882-ceb303dad66f')
