values
  ('ec3a7d27-966b-5e6b-81db-45e972471906', null, (select id from public.skills where slug = 'read-g11-figurative-language'), null, 'medium',
   $q$Ms. Adeyemi says, "If you want to get up it faster, slow down at the bottom." What does this paradox mean?$q$, $q$[{"text":"Runners should walk the first half of every race to stay safe.","is_correct":false,"misconception_token":"overgeneralizes"},{"text":"Saving energy early lets a runner finish the climb more strongly.","is_correct":true},{"text":"Runners who start fast always win races on hilly courses.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The bottom of the hill is steeper than the top, so care is needed.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Saving energy early lets a runner finish the climb more strongly.$q$, $q$When Priya slows down, she "still had breath left" near the top and passes four runners, so pacing early produces a faster finish. The advice is about this hill, not about walking every race.$q$, 'draft', '58f2c27b-5111-5491-9882-ceb303dad66f')
