values
  ('61cc8db8-9ea0-5797-b772-cb21cf818e55', null, (select id from public.skills where slug = 'read-g11-figurative-language'), null, 'medium',
   $q$The runners ahead of Priya were "laboring." Why is "laboring" a stronger choice here than "working"?$q$, $q$[{"text":"\"Laboring\" means the runners were being paid to race that day.","is_correct":false,"misconception_token":"wrong-meaning-of-word"},{"text":"\"Laboring\" suggests that the runners were moving with ease.","is_correct":false,"misconception_token":"confuses-opposite"},{"text":"\"Laboring\" shows that the runners were speeding up the hill.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"\"Laboring\" suggests heavy strain and struggle, not just effort.","is_correct":true}]$q$::jsonb, $q$"Laboring" suggests heavy strain and struggle, not just effort.$q$, $q$Both words involve effort, but "laboring" carries a sense of hard, painful struggle, which contrasts with Priya still having "breath left." The "paid" meaning belongs to a different sense of labor that does not fit a race.$q$, 'draft', '58f2c27b-5111-5491-9882-ceb303dad66f')
