values
  ('28ce4259-ec79-53a7-a1d2-096c5197b96e', null, (select id from public.skills where slug = 'read-g11-figurative-language'), null, 'hard',
   $q$An imaginary island was reprinted so often "that it gained the appearance of certainty." Why does the author use "appearance of certainty" instead of simply "certainty"?$q$, $q$[{"text":"To show that the island was finally confirmed by later explorers","is_correct":false,"misconception_token":"contradicts-text"},{"text":"To signal that repeated copying made the island look proven when it was not","is_correct":true},{"text":"To describe how beautifully the island was drawn and colored","is_correct":false,"misconception_token":"wrong-meaning-of-word"},{"text":"To suggest that mapmakers were truly certain the island existed","is_correct":false,"misconception_token":"misses-qualifier"}]$q$::jsonb, $q$To signal that repeated copying made the island look proven when it was not$q$, $q$"Appearance" separates how the island seemed from what was true: no sailor had seen it, yet repetition made it look confirmed. Reading "appearance" as the island's visual look ignores that the phrase is about confidence, not drawing style.$q$, 'draft', '785f8d37-79b3-5bda-9bc0-56a4f5a84eee')
