  ('c89ed0d0-1773-58b6-8ca1-4ef3c8029b4a', null, (select id from public.skills where slug = 'read-g11-figurative-language'), null, 'medium',
   $q$The narrator describes "squat ceramic" lamps beside tall brass ones. What does "squat" add that a word like "small" would not?$q$, $q$[{"text":"It shows that the lamps were placed in a crouching position.","is_correct":false,"misconception_token":"wrong-meaning-of-word"},{"text":"It means exactly the same as \"small,\" so it adds nothing.","is_correct":false,"misconception_token":"ignores-connotation"},{"text":"It suggests that the ceramic lamps were cracked or broken.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It suggests the lamps were short and thick, unlike the tall ones.","is_correct":true}]$q$::jsonb, $q$It suggests the lamps were short and thick, unlike the tall ones.$q$, $q$"Squat" describes something short and wide, sharpening the contrast with the "tall brass floor lamps." Lamps cannot crouch, so the crouching sense of the word does not fit here.$q$, 'draft', 'ec8d744b-1d31-56d1-934a-eec6d0c0236b')
