  ('76333eaf-7c3b-511b-a6ff-129059d077da', null, (select id from public.skills where slug = 'read-g11-figurative-language'), null, 'easy',
   $q$Amara's board "looked like a quiet field after a storm." What does this comparison suggest?$q$, $q$[{"text":"The game had just begun, and the board was still full of pieces.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Many pieces had been captured, leaving a calm board after intense play.","is_correct":true},{"text":"The players had knocked the pieces over by accident during the game.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The tournament was being held outdoors in a field after bad weather.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$Many pieces had been captured, leaving a calm board after intense play.$q$, $q$The next sentence, "Most of the pieces were gone," shows the storm stands for the earlier battle and the quiet field for the nearly empty board. The game had lasted three hours, so it had not just begun.$q$, 'draft', '936952f3-ff9f-55d2-b339-31906970cce9')
