values
  ('b0d28b99-a4a3-509f-838b-cd5b3468e54f', null, (select id from public.skills where slug = 'read-g11-literary-structure-pov'), null, 'medium',
   $q$Why does the fable end with the heron flying south hungry rather than finally catching the best fish?$q$, $q$[{"text":"The unhappy ending suggests the heron's ledger was full of mistakes about the fish it studied.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The unhappy ending drives home the lesson that preparation without action can come too late.","is_correct":true},{"text":"The unhappy ending shows that the kingfisher's method also fails once the winter arrives.","is_correct":false,"misconception_token":"too-narrow"},{"text":"The unhappy ending leaves the lesson unclear so that readers can invent their own moral.","is_correct":false,"misconception_token":"misreads-purpose"}]$q$::jsonb, $q$The unhappy ending drives home the lesson that preparation without action can come too late.$q$, $q$The heron is "ready, at last, to begin" on the very night the frost comes, so the timing of the ending makes the delay itself the mistake. The text says the ledger described every fish, so its accuracy is not the problem.$q$, 'draft', '1f423d1b-86a2-5d31-bb69-326e28f42f48')
