values
  ('6905c4a8-a12c-529c-8f53-be23f20524a2', null, (select id from public.skills where slug = 'read-g11-literary-structure-pov'), null, 'hard',
   $q$Which detail best shows that the narrator does not share the heron's high opinion of its own method?$q$, $q$[{"text":"\"The ledger grew thick. The heron grew thin.\"","is_correct":true},{"text":"\"Each morning it recorded every fish that passed its legs.\"","is_correct":false,"misconception_token":"misreads-tone"},{"text":"\"The kingfisher agreed that it had no idea.\"","is_correct":false,"misconception_token":"misreads-character"},{"text":"\"It knew which ones were fattest, which were slowest.\"","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$"The ledger grew thick. The heron grew thin."$q$, $q$The paired short sentences set the ledger's growth against the heron's hunger, a dry comment that the method is harming it. Lines such as "Each morning it recorded every fish" simply report what the heron or kingfisher did or knew, without the narrator's judgment.$q$, 'draft', '1f423d1b-86a2-5d31-bb69-326e28f42f48')
