values
  ('fd3a7185-ef1b-506b-b3da-fb45acc0f2a3', null, (select id from public.skills where slug = 'read-g11-literary-structure-pov'), null, 'hard',
   $q$How does the final sentence complete the story's structure?$q$, $q$[{"text":"It ends with a confession, so the narrator finally admits the nerves that were hidden throughout the story.","is_correct":false,"misconception_token":"misses-irony"},{"text":"It ends with one more excuse, so the narrator's denial stays unbroken while the reader's understanding is complete.","is_correct":true},{"text":"It ends with a new problem, so the reader expects a sequel about the narrator's next recital performance.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It ends with the mother's view, so the story's point of view shifts to a more reliable adult observer.","is_correct":false,"misconception_token":"confuses-point-of-view"}]$q$::jsonb, $q$It ends with one more excuse, so the narrator's denial stays unbroken while the reader's understanding is complete.$q$, $q$Gulping a whole bottle "because ... the auditorium was very dry" is another cover story, so the narrator never cracks even as the reader sees the truth clearly. Nothing in the sentence is a confession, and the narration stays with the same speaker.$q$, 'draft', '7ab98993-2aaa-5cad-9fd7-88d6ee505a25')
