values
  ('d395bfea-a38f-5d2b-9bc6-440bbcf40b2c', null, (select id from public.skills where slug = 'read-g11-literary-structure-pov'), null, 'medium',
   $q$What does the speaker really mean by calling Desmond's schedule "so beautiful that no one dared to follow it"?$q$, $q$[{"text":"The schedule was hidden from the others so that Desmond could take all the credit.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The schedule was so strict that the group felt frightened of missing any deadline.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The schedule looked impressive but was useless, since no one actually used it.","is_correct":true},{"text":"The schedule was the most valuable part of the project and earned the high grade.","is_correct":false,"misconception_token":"takes-speaker-literally"}]$q$::jsonb, $q$The schedule looked impressive but was useless, since no one actually used it.$q$, $q$The praise is ironic: "no one dared to follow it" means the schedule was decoration, not a plan. Taking "dared" literally as fear misses that the line mocks effort spent on looks instead of work.$q$, 'draft', 'ba6346df-0ea0-5d96-88cf-18925cb69cdd')
