values
  ('78e2f5ae-723d-598d-8f66-405c221f3ac8', null, (select id from public.skills where slug = 'read-g11-literary-structure-pov'), null, 'hard',
   $q$How do the final two lines change the poem's approach to its subject?$q$, $q$[{"text":"They drop the mock praise for a direct question, making the satire's real point about fairness explicit.","is_correct":true},{"text":"They shift to a new subject, making the poem end with a separate complaint about how teachers grade.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"They continue the sincere praise, making clear that the speaker approves of sharing the grade equally.","is_correct":false,"misconception_token":"takes-speaker-literally"},{"text":"They reveal a new speaker, making Priya herself the one who has been telling the entire tale.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$They drop the mock praise for a direct question, making the satire's real point about fairness explicit.$q$, $q$After "as the heavens intended," a mock approval of the unfair grade, the closing "ask who is doing the work" speaks plainly and names the target. The lines stay on group work rather than turning to teachers, and no new speaker appears.$q$, 'draft', 'ba6346df-0ea0-5d96-88cf-18925cb69cdd')
