values
  ('9dff3c65-fa5a-569c-898c-8c32cc548ec6', null, (select id from public.skills where slug = 'read-g11-literary-structure-pov'), null, 'medium',
   $q$How does telling the reader about the missing word in the first paragraph affect the rest of the story?$q$, $q$[{"text":"The reader learns the ending early, so the town's preparations are left out of the story.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The reader shares the town's ignorance, so the crate is as surprising to the reader as to them.","is_correct":false,"misconception_token":"reverses-structure"},{"text":"The reader knows the truth while the town does not, so every preparation becomes comic.","is_correct":true},{"text":"The reader suspects Odalys of a crime, so the story turns into a mystery about the telegraph.","is_correct":false,"misconception_token":"misreads-genre"}]$q$::jsonb, $q$The reader knows the truth while the town does not, so every preparation becomes comic.$q$, $q$Because the reader learns at once that SAW was lost, the pies, songs and banner are funny as dramatic irony. The reader is not surprised by the crate; only the townspeople are.$q$, 'draft', 'e6cfc567-cd22-59c1-bc46-50a863751977')
