  ('7709a852-5ac2-5d25-9c65-53b384ecb5ff', null, (select id from public.skills where slug = 'read-g11-story-details-inference'), null, 'hard',
   $q$Which statement best describes what the passage leaves uncertain?$q$, $q$[{"text":"Whether the debt was forgiven or settled by work such as fixing the pump.","is_correct":true},{"text":"Whether Pruitt ran the store during the year 1934.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Whether Dev copied the four words from the slip into his note.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Whether the Castellano entries were ever marked as paid.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$Whether the debt was forgiven or settled by work such as fixing the pump.$q$, $q$The undated slip and the initials "R.C." hint at payment by labor but never confirm it, so Dev's reading and Mrs. Halvorsen's both stay possible. Pruitt ran the store from 1924 to 1938, so that fact is stated.$q$, 'draft', 'ec3b98c9-71ed-544e-9759-eba25dd6a1df')
