  ('e56017ce-d70e-5040-82e6-3ddb731894b2', null, (select id from public.skills where slug = 'read-g11-story-details-inference'), null, 'hard',
   $q$Which pair of details best supports the inference that Brisk's final acorn pays for something other than an echo?$q$, $q$[{"text":"She stands long at the spring, and then she pays without shouting.","is_correct":true},{"text":"The sign reads ECHOES, and the travelers shout riddle answers.","is_correct":false,"misconception_token":"wrong-subject"},{"text":"The fox oils his box, and the canyon walls lean close.","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"She comes down the trail alone, and the season is autumn.","is_correct":false,"misconception_token":"irrelevant-detail"}]$q$::jsonb, $q$She stands long at the spring, and then she pays without shouting.$q$, $q$Her long pause at the improved spring followed by paying without using the echo connects the payment to the trail's care. The sign and the riddles concern the echo itself, which she pointedly does not buy.$q$, 'draft', '6ca79473-7f0b-539b-8f69-1fa6e082c138')
