  ('10f1aadb-9ae8-5648-b46d-6373cb47e0ff', null, (select id from public.skills where slug = 'read-g11-story-details-inference'), null, 'hard',
   $q$Which statement best identifies something the passage leaves uncertain?$q$, $q$[{"text":"Whether the projector was really the cause of the early captions.","is_correct":true},{"text":"Where the LED sign for the captions came from.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Whether the captions were working well by the half hour.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"How many people came to film night that Saturday.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$Whether the projector was really the cause of the early captions.$q$, $q$The cause is only Noor's guess ("She guessed that the projector..."), never confirmed. Sami laughing in time with the crowd shows the captions were working, and the sign's source and crowd size are stated.$q$, 'draft', 'd931dcbc-3463-57a9-9989-863b2dad859c')
