  ('17bd1745-b76c-5579-aaad-0f9993031fd5', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'hard',
   $q$How does the final line add a second theme that builds on the theme of witnessing?$q$, $q$[{"text":"It moves the focus from the glacier to the speaker's wish to become stronger.","is_correct":false,"misconception_token":"misidentifies-theme"},{"text":"It suggests the speaker hopes to replace the aunt because her measurements are wrong.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It shows the duty of witnessing being handed from one generation to the next, so the act of attention continues.","is_correct":true},{"text":"It shows that the speaker has decided the work is pointless and will end it soon.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$It shows the duty of witnessing being handed from one generation to the next, so the act of attention continues.$q$, $q$Carrying "the stakes myself" means the speaker is taking on the aunt's role, linking witnessing to inheritance. Nothing suggests the aunt's numbers are wrong; the poem calls her ink "careful."$q$, 'draft', '5014dedd-4788-5a9b-815f-3c11a732119c')
