-- Passage rg11-theme-summary-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('391883cd-e59b-59f4-96ca-3600b90501f6', 'rg11-theme-summary-p05', (select id from public.skills where slug = 'read-g11-theme-summary'), null,
        '9-12', $q$The Bridge Inspector$q$, $q$My father inspects bridges after midnight,
when the traffic thins to a few late trucks
and the river underneath is louder than the road.
He carries a hammer with a small round head
and taps the steel the way a doctor taps a knee,
listening for the one dull note in a hundred clear ones.

When I was nine I thought it was a lonely job.
Nobody waves at the man under the bridge.
Nobody sees him in the morning, when the buses cross
and the joggers cross and the commuters cross,
every one of them trusting a thing they never think about.

Last spring he let me come along.
I held the flashlight while he tapped and wrote,
tapped and wrote, until the sky behind the towers
went from black to the color of weak tea.
He found one bolt that sounded wrong and circled it in chalk.
That one, he said, is why we came.

I understand it better now.
Some work is measured by what never happens:
the crack that never spreads, the beam that never bends,
the ordinary morning that stays ordinary.
He does not need the joggers to look down.

Still, when I cross the river on the bus to school,
I press my palm flat against the window glass
and feel the hum of the steel beneath the wheels,
and I listen the way he taught me,
for the clear notes, and for the one that isn't.$q$, 'draft')
