  ('78a5f181-2cbb-5191-8176-bc190d4704bc', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'medium',
   $q$What role does the line "Some work is measured by what never happens" play in the poem?$q$, $q$[{"text":"It shows that the father dislikes his job and wants to change careers.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It states the speaker's new understanding directly and connects the details that follow it.","is_correct":true},{"text":"It introduces a new problem that the father must solve before morning.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"It suggests the speaker believes the father's work accomplishes nothing.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$It states the speaker's new understanding directly and connects the details that follow it.$q$, $q$The line explains the value of the father's work, and the list after the colon gives examples of what "never happens." Reading it as "accomplishes nothing" misses that preventing failure is the point.$q$, 'draft', '391883cd-e59b-59f4-96ca-3600b90501f6')
