  ('c4e2792c-5527-53f7-a5ff-af6c11a11702', null, (select id from public.skills where slug = 'read-g11-word-parts'), null, 'medium',
   $q$The prefix col- means "together," and loqu means "speak." Why did Ms. Delacroix object to Tobias's "colloquial" style?$q$, $q$[{"text":"It sounded like casual conversation instead of formal argument.","is_correct":true},{"text":"It was much too long to finish in the time allowed.","is_correct":false,"misconception_token":"context-only-guess"},{"text":"It used technical words that the judges might not know.","is_correct":false,"misconception_token":"opposite-meaning"},{"text":"It quoted too many other speakers instead of his own ideas.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It sounded like casual conversation instead of formal argument.$q$, $q$Colloquial language is the way people speak together in everyday talk, and the coach contrasts it with how you would "write a strong essay." Technical vocabulary is the opposite of the "kind of" and "you know" phrases in the speech.$q$, 'draft', 'a2ed043a-a576-5361-a12b-59833aa13adb')
