  ('1a07ab57-6662-580f-b4f2-b7fa2d095074', null, (select id from public.skills where slug = 'read-g11-word-parts'), null, 'medium',
   $q$The Latin prefix mal- means "bad" or "badly." What happened when the clock began to "malfunction"?$q$, $q$[{"text":"It was deliberately changed by one of the players.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It ran out of time and ended the game early.","is_correct":false,"misconception_token":"context-only-guess"},{"text":"It stopped working correctly and showed wrong times.","is_correct":true},{"text":"It worked better than the other clocks in the room.","is_correct":false,"misconception_token":"opposite-meaning"}]$q$::jsonb, $q$It stopped working correctly and showed wrong times.$q$, $q$Mal plus function means "function badly," and the clock added minutes to one side while the other "display froze." The arbiter says the problem is "a battery fault, not anyone's doing," so no player changed it.$q$, 'draft', '5a92fa28-9abe-56ef-82f3-14efcea084e7')
